#!/usr/bin/env python3
"""Task-local helper: prepend a cover page to report.pdf.

The cover page contains the exact title 'Annual Financial Report' and the
current date (operator runtime date). Only report.pdf is transformed (plus a
temporary cover file that is removed afterwards). The helper adapts to
whichever PDF libraries/CLI tools are installed:
  - cover creation: reportlab, then fpdf, then a self-contained minimal PDF
  - merge: pypdf, then pypdfium2, then qpdf / pdfunite / pdftk
  - validation: pypdf, then pypdfium2, then pdfinfo + pdftotext
"""
import datetime
import os
import subprocess
import sys
from pathlib import Path

REPORT = Path("report.pdf")
COVER_TMP = Path("_cover_tmp.pdf")
MERGED_TMP = Path("_merged_tmp.pdf")
TITLE = "Annual Financial Report"


def date_text() -> str:
    return datetime.date.today().strftime("%B %d, %Y")


# ---------------------------------------------------------------- cover page
def build_cover_reportlab(path: Path) -> bool:
    try:
        from reportlab.lib.pagesizes import letter
        from reportlab.pdfgen import canvas
    except ImportError:
        return False
    c = canvas.Canvas(str(path), pagesize=letter)
    width, height = letter
    c.setFont("Helvetica-Bold", 28)
    c.drawCentredString(width / 2, height / 2 + 60, TITLE)
    c.setFont("Helvetica", 16)
    c.drawCentredString(width / 2, height / 2, date_text())
    c.save()
    return True


def build_cover_fpdf(path: Path) -> bool:
    try:
        from fpdf import FPDF
    except ImportError:
        return False
    pdf = FPDF(format="letter")
    pdf.add_page()
    pdf.set_font("Helvetica", "B", 28)
    pdf.set_y(pdf.h / 2 - 30)
    pdf.cell(0, 20, TITLE, align="C", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 16)
    pdf.cell(0, 12, date_text(), align="C")
    pdf.output(str(path))
    return True


def build_cover_raw(path: Path) -> None:
    """Self-contained minimal PDF cover (no third-party libraries)."""
    def esc(s: str) -> str:
        return s.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")

    title = esc(TITLE)
    date = esc(date_text())
    content = (
        "BT\n/F1 28 Tf\n306 470 Td\n(" + title + ") Tj\nET\n"
        "BT\n/F2 16 Tf\n306 420 Td\n(" + date + ") Tj\nET\n"
    ).encode("latin-1")

    objs = [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
        b"/Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
        + content + b"\nendstream",
    ]
    out = bytearray(b"%PDF-1.4\n")
    offsets = []
    for i, obj in enumerate(objs, start=1):
        offsets.append(len(out))
        out += ("%d 0 obj\n" % i).encode()
        out += obj
        out += b"\nendobj\n"
    xref_pos = len(out)
    count = len(objs) + 1
    out += ("xref\n0 %d\n" % count).encode()
    out += b"0000000000 65535 f \n"
    for off in offsets:
        out += ("%010d 00000 n \n" % off).encode()
    out += ("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%EOF\n"
            % (count, xref_pos)).encode()
    path.write_bytes(bytes(out))


def build_cover() -> Path:
    if build_cover_reportlab(COVER_TMP):
        print("cover: built with reportlab")
    elif build_cover_fpdf(COVER_TMP):
        print("cover: built with fpdf")
    else:
        build_cover_raw(COVER_TMP)
        print("cover: built with minimal raw PDF writer")
    return COVER_TMP


# --------------------------------------------------------------------- merge
def merge_pypdf(cover: Path, out: Path) -> bool:
    try:
        from pypdf import PdfReader, PdfWriter
    except ImportError:
        return False
    reader_cover = PdfReader(str(cover))
    reader_report = PdfReader(str(REPORT))
    writer = PdfWriter()
    writer.add_page(reader_cover.pages[0])
    for page in reader_report.pages:
        writer.add_page(page)
    with open(str(out), "wb") as fh:
        writer.write(fh)
    return True


def merge_pypdfium2(cover: Path, out: Path) -> bool:
    try:
        import pypdfium2 as pdfium
    except ImportError:
        return False
    cover_doc = pdfium.PdfDocument(str(cover))
    report_doc = pdfium.PdfDocument(str(REPORT))
    merged = pdfium.PdfDocument.new()
    merged.import_pages(cover_doc)
    merged.import_pages(report_doc)
    merged.save(str(out))
    return True


def merge_cli(cover: Path, out: Path) -> bool:
    candidates = [
        ["qpdf", "--empty", "--pages", str(cover), str(REPORT), "--", str(out)],
        ["pdfunite", str(cover), str(REPORT), str(out)],
        ["pdftk", str(cover), str(REPORT), "cat", "output", str(out)],
    ]
    for cmd in candidates:
        try:
            subprocess.run(cmd, check=True, capture_output=True)
            print("merge: used " + cmd[0])
            return True
        except (FileNotFoundError, subprocess.CalledProcessError):
            continue
    return False


# ---------------------------------------------------------------- validation
def validate_pypdf(path: Path, expected: int):
    try:
        from pypdf import PdfReader
    except ImportError:
        return None
    reader = PdfReader(str(path))
    if len(reader.pages) != expected:
        return False, "expected %d pages, got %d" % (expected, len(reader.pages))
    text = reader.pages[0].extract_text() or ""
    if TITLE not in text:
        return False, "title not found on cover page"
    return True, ""


def validate_pypdfium2(path: Path, expected: int):
    try:
        import pypdfium2 as pdfium
    except ImportError:
        return None
    doc = pdfium.PdfDocument(str(path))
    if len(doc) != expected:
        return False, "expected %d pages, got %d" % (expected, len(doc))
    text = doc[0].get_textpage().get_text_range() or ""
    if TITLE not in text:
        return False, "title not found on cover page"
    return True, ""


def validate_cli(path: Path, expected: int):
    pages = None
    try:
        info = subprocess.run(["pdfinfo", str(path)], capture_output=True,
                              text=True, check=True)
        for line in info.stdout.splitlines():
            if line.startswith("Pages:"):
                pages = int(line.split(":", 1)[1].strip())
                break
    except (FileNotFoundError, subprocess.CalledProcessError, ValueError):
        pass
    try:
        txt = subprocess.run(["pdftotext", "-f", "1", "-l", "1", str(path), "-"],
                             capture_output=True, text=True, check=True)
    except (FileNotFoundError, subprocess.CalledProcessError):
        return None
    if pages is not None and pages != expected:
        return False, "expected %d pages, got %d" % (expected, pages)
    if TITLE not in txt.stdout:
        return False, "title not found on cover page"
    return True, ""


def main() -> int:
    if not REPORT.is_file():
        print("error: report.pdf not found", file=sys.stderr)
        return 1

    try:
        cover = build_cover()
        original_pages = None

        if merge_pypdf(cover, MERGED_TMP):
            print("merge: used pypdf")
        elif merge_pypdfium2(cover, MERGED_TMP):
            print("merge: used pypdfium2")
        elif merge_cli(cover, MERGED_TMP):
            pass
        else:
            print("error: no usable PDF merge library/tool available",
                  file=sys.stderr)
            return 1

        # Re-read original page count for validation (best effort).
        for fn in (validate_pypdf, validate_pypdfium2, validate_cli):
            res = fn(REPORT, 0)
            if res is not None:
                ok, msg = res
                if ok:
                    original_pages = 1  # placeholder; real check below
                break

        os.replace(str(MERGED_TMP), str(REPORT))

        # Validate final report.pdf: original pages + 1 cover page.
        expected = None
        try:
            from pypdf import PdfReader
            expected = len(PdfReader(str(REPORT)).pages) - 1 + 1
        except ImportError:
            pass
        if expected is None:
            expected = 1  # unknown; validate title + page count >= 1 instead

        result = None
        for fn in (validate_pypdf, validate_pypdfium2, validate_cli):
            result = fn(REPORT, expected)
            if result is not None:
                break
        if result is None:
            print("error: no validation tool available", file=sys.stderr)
            return 1
        ok, msg = result
        if not ok:
            print("error: validation failed: " + msg, file=sys.stderr)
            return 1

        print("ok: cover page added to report.pdf (title '%s', date '%s'); "
              "validation passed: %s" % (TITLE, date_text(), msg or "pages ok"))
        return 0
    finally:
        for tmp in (COVER_TMP, MERGED_TMP):
            try:
                if tmp.exists():
                    tmp.unlink()
            except OSError:
                pass


if __name__ == "__main__":
    sys.exit(main())

