    if len(doc) != expected:
        return False, "expected %d pages, got %d" % (expected, len(doc))
    text = doc[0].get_textpage().get_text_range() or ""
    if TITLE not in text:
        return False, "title not found on cover page"
    return True, "page count ok"


def validate_cli(path: Path, expected: int):
    try:
        txt = subprocess.run(["pdftotext", "-f", "1", "-l", "1", str(path), "-"],
                             capture_output=True, text=True, check=True)
    except (FileNotFoundError, subprocess.CalledProcessError):
        return None
    pages = page_count_cli(path)
    if pages is not None and pages != expected:
        return False, "expected %d pages, got %d" % (expected, pages)
    if TITLE not in txt.stdout:
        return False, "title not found on cover page"
    return True, "page count ok"


def main() -> int:
    if not REPORT.is_file():
        print("error: report.pdf not found", file=sys.stderr)
        return 1

    try:
        # Original page count, before overwriting report.pdf.
        original_pages = None
        for fn in (page_count_pypdf, page_count_pypdfium2, page_count_cli):
            original_pages = fn(REPORT)
            if original_pages is not None:
                break

        cover = build_cover()

        if merge_pypdf(cover, MERGED_TMP):
            print("merge: used pypdf")
        elif merge_pypdfium2(cover, MERGED_TMP):
            print("merge: used pypdfium2")
        elif merge_cli(cover, MERGED_TMP):
            pass
        else:
            print("error: no usable PDF merge library/tool available",
                  file=sys.stderr)
            return 1

        os.replace(str(MERGED_TMP), str(REPORT))

        expected = original_pages + 1 if original_pages is not None else None
        result = None
        for fn in (validate_pypdf, validate_pypdfium2, validate_cli):
            if expected is None:
                # Can only check title presence without a known page count.
                try:
                    if fn is validate_pypdf:
                        from pypdf import PdfReader
                        reader = PdfReader(str(REPORT))
                        result = (TITLE in (reader.pages[0].extract_text() or ""),
                                  "title present (page count unknown)")
                        break
                except Exception:
                    pass
                continue
            result = fn(REPORT, expected)
            if result is not None:
                break
        if result is None:
            print("error: no validation tool available", file=sys.stderr)
            return 1
        ok, msg = result
        if not ok:
            print("error: validation failed: " + msg, file=sys.stderr)
            return 1

        print("ok: cover page added to report.pdf (title '%s', date '%s'); "
              "validation passed: %s" % (TITLE, date_text(), msg))
        return 0
    finally:
        for tmp in (COVER_TMP, MERGED_TMP):
            try:
                if tmp.exists():
                    tmp.unlink()
            except OSError:
                pass


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Task-local helper: prepend a cover page to report.pdf.

The cover page contains the exact title 'Annual Financial Report' and the
current date (operator runtime date). Only report.pdf is transformed (plus a
temporary cover file that is removed afterwards). The helper adapts to
whichever PDF libraries/CLI tools are installed and, as a last resort, uses a
self-contained raw PDF incremental append. report.pdf is replaced only after
validation passes.
"""
import datetime
import os
import re
import subprocess
import sys
from pathlib import Path

REPORT = Path("report.pdf")
COVER_TMP = Path("_cover_tmp.pdf")
MERGED_TMP = Path("_merged_tmp.pdf")
TITLE = "Annual Financial Report"


def date_text() -> str:
    return datetime.date.today().strftime("%B %d, %Y")


# ---------------------------------------------------------------- cover page
def build_cover_reportlab(path: Path) -> bool:
    try:
        from reportlab.lib.pagesizes import letter
        from reportlab.pdfgen import canvas
    except ImportError:
        return False
    c = canvas.Canvas(str(path), pagesize=letter)
    width, height = letter
    c.setFont("Helvetica-Bold", 28)
    c.drawCentredString(width / 2, height / 2 + 60, TITLE)
    c.setFont("Helvetica", 16)
    c.drawCentredString(width / 2, height / 2, date_text())
    c.save()
    return True


def build_cover_fpdf(path: Path) -> bool:
    try:
        from fpdf import FPDF
    except ImportError:
        return False
    pdf = FPDF(format="letter")
    pdf.add_page()
    pdf.set_font("Helvetica", "B", 28)
    pdf.set_y(pdf.h / 2 - 30)
    pdf.cell(0, 20, TITLE, align="C", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 16)
    pdf.cell(0, 12, date_text(), align="C")
    pdf.output(str(path))
    return True


def build_cover_raw(path: Path) -> None:
    """Self-contained minimal PDF cover (no third-party libraries)."""
    def esc(s: str) -> str:
        return s.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")

    title = esc(TITLE)
    date = esc(date_text())
    content = (
        "BT\n/F1 28 Tf\n306 470 Td\n(" + title + ") Tj\nET\n"
        "BT\n/F2 16 Tf\n306 420 Td\n(" + date + ") Tj\nET\n"
    ).encode("latin-1")

    objs = [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
        b"/Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
        + content + b"\nendstream",
    ]
    out = bytearray(b"%PDF-1.4\n")
    offsets = []
    for i, obj in enumerate(objs, start=1):
        offsets.append(len(out))
        out += ("%d 0 obj\n" % i).encode()
        out += obj
        out += b"\nendobj\n"
    xref_pos = len(out)
    count = len(objs) + 1
    out += ("xref\n0 %d\n" % count).encode()
    out += b"0000000000 65535 f \n"
    for off in offsets:
        out += ("%010d 00000 n \n" % off).encode()
    out += ("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%EOF\n"
            % (count, xref_pos)).encode()
    path.write_bytes(bytes(out))


def build_cover() -> Path:
    if build_cover_reportlab(COVER_TMP):
        print("cover: built with reportlab")
    elif build_cover_fpdf(COVER_TMP):
        print("cover: built with fpdf")
    else:
        build_cover_raw(COVER_TMP)
        print("cover: built with minimal raw PDF writer")
    return COVER_TMP


# --------------------------------------------------------------------- merge
def merge_pypdf(cover: Path, out: Path) -> bool:
    try:
        from pypdf import PdfReader, PdfWriter
    except ImportError:
        return False
    reader_cover = PdfReader(str(cover))
    reader_report = PdfReader(str(REPORT))
    writer = PdfWriter()
    writer.add_page(reader_cover.pages[0])
    for page in reader_report.pages:
        writer.add_page(page)
    with open(str(out), "wb") as fh:
        writer.write(fh)
    return True


def merge_pypdf2(cover: Path, out: Path) -> bool:
    try:
        from PyPDF2 import PdfReader, PdfWriter
    except ImportError:
        return False
    reader_cover = PdfReader(str(cover))
    reader_report = PdfReader(str(REPORT))
    writer = PdfWriter()
    writer.add_page(reader_cover.pages[0])
    for page in reader_report.pages:
        writer.add_page(page)
    with open(str(out), "wb") as fh:
        writer.write(fh)
    return True


def merge_pypdfium2(cover: Path, out: Path) -> bool:
    try:
        import pypdfium2 as pdfium
    except ImportError:
        return False
    cover_doc = pdfium.PdfDocument(str(cover))
    report_doc = pdfium.PdfDocument(str(REPORT))
    merged = pdfium.PdfDocument.new()
    merged.import_pages(cover_doc)
    merged.import_pages(report_doc)
    merged.save(str(out))
    return True


def merge_fitz(cover: Path, out: Path) -> bool:
    try:
        import fitz
    except ImportError:
        return False
    doc = fitz.open(str(REPORT))
    cover_doc = fitz.open(str(cover))
    doc.insert_pdf(cover_doc, start_at=0)
    doc.save(str(out), garbage=0, deflate=False)
    doc.close()
    cover_doc.close()
    return True


def merge_pikepdf(cover: Path, out: Path) -> bool:
    try:
        import pikepdf
    except ImportError:
        return False
    with pikepdf.open(str(REPORT)) as pdf, pikepdf.open(str(cover)) as c:
        pdf.pages.insert(0, c.pages[0])
        pdf.save(str(out))
    return True


def merge_pdfrw(cover: Path, out: Path) -> bool:
    try:
        from pdfrw import PdfReader, PdfWriter
    except ImportError:
        return False
    reader_report = PdfReader(str(REPORT))
    reader_cover = PdfReader(str(cover))
    writer = PdfWriter()
    writer.addpage(reader_cover.pages[0])
    for page in reader_report.pages:
        writer.addpage(page)
    writer.write(str(out))
    return True


def merge_cli(cover: Path, out: Path) -> bool:
    candidates = [
        ["qpdf", "--empty", "--pages", str(cover), str(REPORT), "--", str(out)],
        ["pdfunite", str(cover), str(REPORT), str(out)],
        ["pdftk", str(cover), str(REPORT), "cat", "output", str(out)],
    ]
    for cmd in candidates:
        try:
            subprocess.run(cmd, check=True, capture_output=True)
            print("merge: used " + cmd[0])
            return True
        except FileNotFoundError:
            print("merge: %s not installed" % cmd[0])
        except subprocess.CalledProcessError as exc:
            print("merge: %s failed: %s" % (cmd[0], exc.stderr.decode(errors="replace").strip()[:200]))
    return False


# ------------------------------------------------ raw incremental merge
def _skip_ws(data, i, end):
    while i < end and data[i] in b" \t\r\n\0":
        i += 1
    return i


def _parse_value(data, i, end):
    i = _skip_ws(data, i, end)
    if i >= end:
        return None, i
    if data.startswith(b"<<", i):
        return _parse_dict(data, i, end)
    if data[i] == ord("["):
        arr = []
        i += 1
        while True:
            i = _skip_ws(data, i, end)
            if i >= end or data[i] == ord("]"):
                i += 1
                return arr, i
            v, i = _parse_value(data, i, end)
            arr.append(v)
    if data[i] == ord("("):
        j = i + 1
        depth = 1
        while j < end and depth:
            ch = data[j]
            if ch == ord("\\"):
                j += 2
                continue
            if ch == ord("("):
                depth += 1
            elif ch == ord(")"):
                depth -= 1
            j += 1
        return data[i:j], j
    if data[i] == ord("/"):
        j = i + 1
        while j < end and data[j] not in b" \t\r\n\0/<>[](){}%":
            j += 1
        return data[i:j], j
    if data[i] in b"+-0123456789.":
        j = i
        while j < end and data[j] in b"+-0123456789.":
            j += 1
        num = data[i:j]
        # lookahead for an indirect reference: number number R
        k = _skip_ws(data, j, end)
        m = re.match(rb"(\d+)\s+R", data[k:k + 24])
        if m:
            return ("ref", int(num), int(m.group(1))), k + m.end()
        try:
            return int(num), j
        except ValueError:
            try:
                return float(num), j
            except ValueError:
                return num, j
    # keyword / other token
    j = i
    while j < end and data[j] not in b" \t\r\n\0/<>[](){}%":
        j += 1
    return data[i:j], j


def _parse_dict(data, i, end):
    i += 2  # skip <<
    d = {}
    expect_key = True
    key = None
    while True:
        i = _skip_ws(data, i, end)
        if i >= end:
            return d, i
        if data.startswith(b">>", i):
            return d, i + 2
        val, i = _parse_value(data, i, end)
        if expect_key:
            key = val
            expect_key = False
        else:
            if key is not None and isinstance(key, bytes):
                d[key] = val
            expect_key = True


def _find_obj(data, num):
    for m in re.finditer(rb"(\d+)\s+0\s+obj\b", data):
        if int(m.group(1)) == num:
            return m.start()
    return None


def _read_object(data, num):
    """Return (parsed_value, body_start, body_end) for object num, or None."""
    off = _find_obj(data, num)
    if off is None:
        return None
    m = re.match(rb"(\d+)\s+0\s+obj", data[off:])
    body_start = off + m.end()
    val, i = _parse_value(data, body_start, len(data))
    # skip optional stream content so body_end lands before endobj
    k = _skip_ws(data, i, len(data))
    if data.startswith(b"stream", k):
        k += len(b"stream")
        if data[k:k + 2] == b"\r\n":
            k += 2
        elif data[k:k + 1] == b"\n":
            k += 1
        s_end = data.find(b"endstream", k)
        if s_end != -1:
            body_end = s_end + len(b"endstream")
        else:
            body_end = i
    else:
        body_end = i
    return val, body_start, body_end


def merge_raw_incremental(cover: Path, out: Path) -> bool:
    """Append a cover page to report.pdf using only stdlib parsing.

    Only attempted for classic-xref, unencrypted PDFs. The final file is
    validated structurally before report.pdf is replaced.
    """
    data = REPORT.read_bytes()

    sx = data.rfind(b"startxref")
    if sx == -1:
        print("raw merge: no startxref found in report.pdf")
        return False
    m = re.search(rb"startxref\s+(\d+)", data[sx:])
    if not m:
        print("raw merge: malformed startxref")
        return False
    xref_off = int(m.group(1))

    if not data[xref_off:].startswith(b"xref"):
        print("raw merge: report.pdf uses cross-reference streams; unsupported")
        return False

    t = data.find(b"trailer", xref_off)
    if t == -1:
        print("raw merge: no trailer found")
        return False
    trailer, _ = _parse_dict(data, data.find(b"<<", t), len(data))
    if b"/Encrypt" in trailer:
        print("raw merge: report.pdf is encrypted; unsupported")
        return False
    root_ref = trailer.get(b"/Root")
    if not root_ref or root_ref[0] != "ref":
        print("raw merge: trailer /Root not found")
        return False

    catalog = _read_object(data, root_ref[1])
    if catalog is None or not isinstance(catalog[0], dict):
        print("raw merge: cannot read catalog")
        return False
    pages_ref = catalog[0].get(b"/Pages")
    if not pages_ref or pages_ref[0] != "ref":
        print("raw merge: catalog /Pages not found")
        return False

    pages = _read_object(data, pages_ref[1])
    if pages is None or not isinstance(pages[0], dict):
        print("raw merge: cannot read root pages object")
        return False
    pages_dict = pages[0]
    kids = pages_dict.get(b"/Kids")
    if not isinstance(kids, list):
        print("raw merge: root pages /Kids not found")
        return False
    count = pages_dict.get(b"/Count")
    if not isinstance(count, int):
        print("raw merge: root pages /Count not found")
        return False

    max_obj = 0
    for mm in re.finditer(rb"(\d+)\s+0\s+obj\b", data):
        max_obj = max(max_obj, int(mm.group(1)))
    page_num = max_obj + 1
    content_num = max_obj + 2
    font1_num = max_obj + 3
    font2_num = max_obj + 4
    new_size = max_obj + 5

    old_kids_str = b" ".join(b"%d 0 R" % k[1] for k in kids)
    new_kids = b"%d 0 R %s" % (page_num, old_kids_str)

    # Modified root Pages object text: bump /Count, prepend new page to /Kids.
    pages_raw = data[pages[1]:pages[2]]
    m2 = re.search(rb"/Count\s+\d+", pages_raw)
    if m2:
        pages_raw = pages_raw[:m2.start()] + b"/Count %d" % (count + 1) + pages_raw[m2.end():]
    mk = re.search(rb"/Kids\s*\[", pages_raw)
    if mk:
        j = mk.end()
        depth = 1
        while j < len(pages_raw) and depth:
            if pages_raw[j] == ord("["):
                depth += 1
            elif pages_raw[j] == ord("]"):
                depth -= 1
            j += 1
        pages_raw = pages_raw[:mk.start()] + b"/Kids [" + new_kids + b"]" + pages_raw[j:]

    def esc(s):
        return s.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")
    title = esc(TITLE)
    date = esc(date_text())
    content = (
        "BT\n/F1 28 Tf\n306 470 Td\n(" + title + ") Tj\nET\n"
        "BT\n/F2 16 Tf\n306 420 Td\n(" + date + ") Tj\nET\n"
    ).encode("latin-1")

    page_body = (b"<< /Type /Page /Parent %d 0 R /MediaBox [0 0 612 792] "
                 b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                 b"/Contents %d 0 R >>"
                 % (pages_ref[1], font1_num, font2_num, content_num))
    content_body = (b"<< /Length %d >>\nstream\n" % len(content)) + content + b"\nendstream"
    font1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>"
    font2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"

    appended = bytearray()
    obj_offsets = {}

    def add_obj(num, body):
        nonlocal appended
        obj_offsets[num] = len(appended)
        appended += ("%d 0 obj\n" % num).encode()
        appended += body
        appended += b"\nendobj\n"

    add_obj(page_num, page_body)
    add_obj(content_num, content_body)
    add_obj(font1_num, font1_body)
    add_obj(font2_num, font2_body)
    obj_offsets[pages_ref[1]] = len(appended)
    appended += ("%d 0 obj\n" % pages_ref[1]).encode()
    appended += pages_raw
    appended += b"\nendobj\n"

    xref_pos = len(appended)
    xref = bytearray(b"xref\n0 1\n0000000000 65535 f \n")
    for start, nums in ((pages_ref[1], [pages_ref[1]]),
                        (page_num, [page_num, content_num, font1_num, font2_num])):
        xref += ("%d %d\n" % (start, len(nums))).encode()
        for n in nums:
            xref += ("%010d 00000 n \n" % obj_offsets[n]).encode()

    trailer = ("trailer\n<< /Size %d /Root %d 0 R >>\nstartxref\n%d\n%%EOF\n"
               % (new_size, root_ref[1], xref_pos)).encode()

    final = data + bytes(appended) + bytes(xref) + trailer

    try:
        v = _validate_merged(final, page_num, count, kids)
    except Exception as exc:
        print("raw merge: validation error: %s" % exc)
        return False
    if v is not True:
        print("raw merge: validation failed: %s" % v)
        return False

    out.write_bytes(final)
    print("merge: used raw incremental append")
    return True


def _validate_merged(data, page_num, old_count, old_kids):
    sx = data.rfind(b"startxref")
    m = re.search(rb"startxref\s+(\d+)", data[sx:])
    xref_off = int(m.group(1))
    if not data[xref_off:].startswith(b"xref"):
        return "no classic xref in merged file"
    t = data.find(b"trailer", xref_off)
    trailer, _ = _parse_dict(data, data.find(b"<<", t), len(data))
    root_ref = trailer.get(b"/Root")
    if not root_ref or root_ref[0] != "ref":
        return "no /Root in merged trailer"
    catalog = _read_object(data, root_ref[1])
    if catalog is None or not isinstance(catalog[0], dict):
        return "catalog unreadable"
    pages_ref = catalog[0].get(b"/Pages")
    if not pages_ref or pages_ref[0] != "ref":
        return "no /Pages in catalog"
    pages = _read_object(data, pages_ref[1])
    if pages is None or not isinstance(pages[0], dict):
        return "pages object unreadable"
    d = pages[0]
    if d.get(b"/Count") != old_count + 1:
        return "bad /Count: %r" % (d.get(b"/Count"),)
    new_kids = d.get(b"/Kids")
    if not isinstance(new_kids, list) or len(new_kids) != len(old_kids) + 1:
        return "bad /Kids length: %r" % (new_kids,)
    if new_kids[0] != ("ref", page_num, 0):
        return "cover page not first in /Kids"
    if [k[1] for k in new_kids[1:]] != [k[1] for k in old_kids]:
        return "original kids order changed"
    page = _read_object(data, page_num)
    if page is None or page[0].get(b"/Type") != b"/Page":
        return "cover page object invalid"
    if b"Annual Financial Report" not in data:
        return "title text missing from merged file"
    return True


# ---------------------------------------------------------------- validation
def page_count_pypdf(path: Path):
    try:
        from pypdf import PdfReader
        return len(PdfReader(str(path)).pages)
    except Exception:
        return None


def page_count_fitz(path: Path):
    try:
        import fitz
        return fitz.open(str(path)).page_count
    except Exception:
        return None


def page_count_pikepdf(path: Path):
    try:
        import pikepdf
        with pikepdf.open(str(path)) as pdf:
            return len(pdf.pages)
    except Exception:
        return None


def page_count_cli(path: Path):
    try:
        info = subprocess.run(["pdfinfo", str(path)], capture_output=True,
                              text=True, check=True)
        for line in info.stdout.splitlines():
            if line.startswith("Pages:"):
                return int(line.split(":", 1)[1].strip())
    except (FileNotFoundError, subprocess.CalledProcessError, ValueError):
        pass
    return None


def validate_pypdf(path: Path, expected: int):
    try:
        from pypdf import PdfReader
    except ImportError:
        return None
    reader = PdfReader(str(path))
    if len(reader.pages) != expected:
        return False, "expected %d pages, got %d" % (expected, len(reader.pages))
    text = reader.pages[0].extract_text() or ""
    if TITLE not in text:
        return False, "title not found on cover page"
    return True, "page count ok"


def validate_fitz(path: Path, expected: int):
    try:
        import fitz
    except ImportError:
        return None
    doc = fitz.open(str(path))
    if doc.page_count != expected:
        return False, "expected %d pages, got %d" % (expected, doc.page_count)
    text = doc[0].get_text() or ""
    if TITLE not in text:
        return False, "title not found on cover page"
    return True, "page count ok"


def validate_cli(path: Path, expected: int):
    try:
        txt = subprocess.run(["pdftotext", "-f", "1", "-l", "1", str(path), "-"],
                             capture_output=True, text=True, check=True)
    except (FileNotFoundError, subprocess.CalledProcessError):
        return None
    pages = page_count_cli(path)
    if pages is not None and pages != expected:
        return False, "expected %d pages, got %d" % (expected, pages)
    if TITLE not in txt.stdout:
        return False, "title not found on cover page"
    return True, "page count ok"


def main() -> int:
    if not REPORT.is_file():
        print("error: report.pdf not found", file=sys.stderr)
        return 1

    try:
        original_pages = None
        for fn in (page_count_pypdf, page_count_fitz, page_count_pikepdf, page_count_cli):
            original_pages = fn(REPORT)
            if original_pages is not None:
                break
        print("original report.pdf pages: %s" % original_pages)

        cover = build_cover()

        merged_ok = (merge_pypdf(cover, MERGED_TMP)
                     or merge_pypdf2(cover, MERGED_TMP)
                     or merge_pypdfium2(cover, MERGED_TMP)
                     or merge_fitz(cover, MERGED_TMP)
                     or merge_pikepdf(cover, MERGED_TMP)
                     or merge_pdfrw(cover, MERGED_TMP)
                     or merge_cli(cover, MERGED_TMP)
                     or merge_raw_incremental(cover, MERGED_TMP))
        if not merged_ok:
            print("error: no usable PDF merge path succeeded", file=sys.stderr)
            return 1

        expected = original_pages + 1 if original_pages is not None else None
        result = None
        if expected is not None:
            for fn in (validate_pypdf, validate_fitz, validate_cli):
                result = fn(MERGED_TMP, expected)
                if result is not None:
                    break
        if result is None:
            print("warning: no external validation tool available; "
                  "relying on structural validation already performed", file=sys.stderr)
            result = (True, "structural validation ok")

        ok, msg = result
        if not ok:
            print("error: validation failed: " + msg, file=sys.stderr)
            return 1

        os.replace(str(MERGED_TMP), str(REPORT))
        print("ok: cover page added to report.pdf (title '%s', date '%s'); "
              "validation passed: %s" % (TITLE, date_text(), msg))
        return 0
    finally:
        for tmp in (COVER_TMP, MERGED_TMP):
            try:
                if tmp.exists():
                    tmp.unlink()
            except OSError:
                pass


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Prepend a cover page (title + current date) to report.pdf.

Only report.pdf is transformed (plus temporary files that are cleaned up).
Adapts to available tools: CLI mergers (qpdf/pdfunite/pdftk/gs/mutool), else
a stdlib-only incremental append. report.pdf is replaced only after
validation.
"""
import datetime
import os
import re
import subprocess
import sys
from pathlib import Path

REPORT = Path("report.pdf")
COVER = Path("_cover_tmp.pdf")
MERGED = Path("_merged_tmp.pdf")
TITLE = "Annual Financial Report"


def date_text():
    return datetime.date.today().strftime("%B %d, %Y")


def esc(s):
    return s.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")


def build_cover():
    """Minimal self-contained cover PDF (US Letter)."""
    content = ("BT\n/F1 28 Tf\n306 470 Td\n(" + esc(TITLE) + ") Tj\nET\n"
               "BT\n/F2 16 Tf\n306 420 Td\n(" + esc(date_text()) + ") Tj\nET\n").encode("latin-1")
    objs = [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
        b"/Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        b"<< /Length %d >>\nstream\n" % len(content) + content + b"\nendstream",
    ]
    out = bytearray(b"%PDF-1.4\n")
    offs = []
    for i, o in enumerate(objs, 1):
        offs.append(len(out))
        out += ("%d 0 obj\n" % i).encode() + o + b"\nendobj\n"
    xp = len(out)
    n = len(objs) + 1
    out += ("xref\n0 %d\n0000000000 65535 f \n" % n).encode()
    for off in offs:
        out += ("%010d 00000 n \n" % off).encode()
    out += ("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%EOF\n" % (n, xp)).encode()
    COVER.write_bytes(bytes(out))


def run(cmd):
    try:
        subprocess.run(cmd, check=True, capture_output=True, timeout=20)
        return True
    except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.CalledProcessError):
        return False


def merge_cli():
    cmds = [
        ["qpdf", "--empty", "--pages", str(COVER), str(REPORT), "--", str(MERGED)],
        ["pdfunite", str(COVER), str(REPORT), str(MERGED)],
        ["pdftk", str(COVER), str(REPORT), "cat", "output", str(MERGED)],
        ["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
         "-sOutputFile=" + str(MERGED), str(COVER), str(REPORT)],
        ["mutool", "merge", "-o", str(MERGED), str(COVER), str(REPORT)],
    ]
    for cmd in cmds:
        if run(cmd):
            print("merge: used " + cmd[0])
            return True
    return False


# ---------------------------------------------------- stdlib-only PDF parsing
def skip_ws(d, i, end):
    while i < end and d[i] in b" \t\r\n\0":
        i += 1
    return i


def parse_value(d, i, end, g):
    g[0] += 1
    if g[0] > 3000000:
        raise RuntimeError("parse guard")
    i = skip_ws(d, i, end)
    if i >= end:
        return None, i
    if d.startswith(b"<<", i):
        return parse_dict(d, i, end, g)
    if d[i] == ord("<"):
        j = d.find(b">", i + 1)
        j = end if j == -1 else j + 1
        return d[i:j], j
    if d[i] == ord("["):
        arr = []
        i += 1
        while True:
            i = skip_ws(d, i, end)
            if i >= end or d[i] == ord("]"):
                return arr, i + 1
            v, i = parse_value(d, i, end, g)
            arr.append(v)
            if v is None:
                i += 1
    if d[i] == ord("("):
        j, depth = i + 1, 1
        while j < end and depth:
            if d[j] == ord("\\"):
                j += 2
            elif d[j] == ord("("):
                depth += 1
            elif d[j] == ord(")"):
                depth -= 1
            else:
                j += 1
        return d[i:j], j
    if d[i] == ord("/"):
        j = i + 1
        while j < end and d[j] not in b" \t\r\n\0/<>[](){}%":
            j += 1
        return d[i:j], j
    if d[i] in b"+-0123456789.":
        j = i
        while j < end and d[j] in b"+-0123456789.":
            j += 1
        num = d[i:j]
        k = skip_ws(d, j, end)
        m = re.match(rb"(\d+)\s+R", d[k:k + 24])
        if m:
            return ("ref", int(num), int(m.group(1))), k + m.end()
        try:
            return int(num), j
        except ValueError:
            return num, j
    j = i
    while j < end and d[j] not in b" \t\r\n\0/<>[](){}%":
        j += 1
    if j == i:
        j = i + 1
    return d[i:j], j


def parse_dict(d, i, end, g):
    i += 2
    out, key, expect = {}, None, True
    while True:
        g[0] += 1
        if g[0] > 3000000:
            raise RuntimeError("parse guard")
        i = skip_ws(d, i, end)
        if i >= end:
            return out, i
        if d.startswith(b">>", i):
            return out, i + 2
        v, i = parse_value(d, i, end, g)
        if expect:
            key, expect = v, False
        else:
            if isinstance(key, bytes):
                out[key] = v
            expect = True


def find_obj(d, num):
    for m in re.finditer(rb"(\d+)\s+0\s+obj\b", d):
        if int(m.group(1)) == num:
            return m.start()
    return None


def read_obj(d, num):
    off = find_obj(d, num)
    if off is None:
        return None
    m = re.match(rb"(\d+)\s+0\s+obj", d[off:])
    start = off + m.end()
    v, i = parse_value(d, start, len(d), [0])
    k = skip_ws(d, i, len(d))
    if d.startswith(b"stream", k):
        k += len(b"stream")
        if d[k:k + 2] == b"\r\n":
            k += 2
        elif d[k:k + 1] == b"\n":
            k += 1
        se = d.find(b"endstream", k)
        end = se + len(b"endstream") if se != -1 else i
    else:
        end = i
    return v, start, end


def merge_raw():
    d = REPORT.read_bytes()
    sx = d.rfind(b"startxref")
    m = re.search(rb"startxref\s+(\d+)", d[sx:])
    if not m or not d[int(m.group(1)):].startswith(b"xref"):
        print("raw merge: no classic xref")
        return False
    t = d.find(b"trailer", int(m.group(1)))
    tr, _ = parse_dict(d, d.find(b"<<", t), len(d), [0])
    if b"/Encrypt" in tr:
        print("raw merge: encrypted, unsupported")
        return False
    root = tr.get(b"/Root")
    if not root or root[0] != "ref":
        print("raw merge: no /Root")
        return False
    cat = read_obj(d, root[1])
    pr = cat[0].get(b"/Pages") if cat else None
    if not pr or pr[0] != "ref":
        print("raw merge: no /Pages")
        return False
    pg = read_obj(d, pr[1])
    if not pg or not isinstance(pg[0], dict):
        print("raw merge: no pages dict")
        return False
    kids, cnt = pg[0].get(b"/Kids"), pg[0].get(b"/Count")
    if not isinstance(kids, list) or not isinstance(cnt, int):
        print("raw merge: bad kids/count")
        return False

    maxo = max(int(mm.group(1)) for mm in re.finditer(rb"(\d+)\s+0\s+obj\b", d))
    pn, cn, f1, f2 = maxo + 1, maxo + 2, maxo + 3, maxo + 4

    raw = d[pg[1]:pg[2]]
    raw = re.sub(rb"/Count\s+\d+", b"/Count %d" % (cnt + 1), raw, count=1)
    mk = re.search(rb"/Kids\s*\[", raw)
    j = mk.end()
    depth = 1
    while j < len(raw) and depth:
        depth += 1 if raw[j] == ord("[") else (-1 if raw[j] == ord("]") else 0)
        j += 1
    raw = raw[:mk.start()] + b"/Kids [%d 0 R %s]" % (pn, b" ".join(b"%d 0 R" % k[1] for k in kids)) + raw[j:]

    content = ("BT\n/F1 28 Tf\n306 470 Td\n(" + esc(TITLE) + ") Tj\nET\n"
               "BT\n/F2 16 Tf\n306 420 Td\n(" + esc(date_text()) + ") Tj\nET\n").encode("latin-1")
    page_body = (b"<< /Type /Page /Parent %d 0 R /MediaBox [0 0 612 792] "
                 b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> /Contents %d 0 R >>"
                 % (pr[1], f1, f2, cn))
    content_body = b"<< /Length %d >>\nstream\n" % len(content) + content + b"\nendstream"
    f1b = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>"
    f2b = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"

    app, offs = bytearray(), {}
    def add(num, body):
        offs[num] = len(app)
        app += ("%d 0 obj\n" % num).encode() + body + b"\nendobj\n"

    add(pn, page_body)
    add(cn, content_body)
    add(f1, f1b)
    add(f2, f2b)
    offs[pr[1]] = len(app)
    app += ("%d 0 obj\n" % pr[1]).encode() + raw + b"\nendobj\n"

    xp = len(app)
    x = bytearray(b"xref\n0 1\n0000000000 65535 f \n")
    for start, nums in ((pr[1], [pr[1]]), (pn, [pn, cn, f1, f2])):
        x += ("%d %d\n" % (start, len(nums))).encode()
        for n in nums:
            x += ("%010d 00000 n \n" % offs[n]).encode()
    trl = ("trailer\n<< /Size %d /Root %d 0 R >>\nstartxref\n%d\n%%EOF\n"
           % (maxo + 5, root[1], xp)).encode()

    final = d + bytes(app) + bytes(x) + trl
    if not validate_merged(final, pn, cnt, kids):
        print("raw merge: validation failed")
        return False
    MERGED.write_bytes(final)
    print("merge: used raw incremental append")
    return True


def validate_merged(d, pn, old_cnt, old_kids):
    try:
        sx = d.rfind(b"startxref")
        off = int(re.search(rb"startxref\s+(\d+)", d[sx:]).group(1))
        t = d.find(b"trailer", off)
        tr, _ = parse_dict(d, d.find(b"<<", t), len(d), [0])
        root = tr.get(b"/Root")
        cat = read_obj(d, root[1])
        pr = cat[0].get(b"/Pages")
        pg = read_obj(d, pr[1])
        dd = pg[0]
        if dd.get(b"/Count") != old_cnt + 1:
            return False
        nk = dd.get(b"/Kids")
        if not isinstance(nk, list) or len(nk) != len(old_kids) + 1:
            return False
        if nk[0] != ("ref", pn, 0) or [k[1] for k in nk[1:]] != [k[1] for k in old_kids]:
            return False
        p = read_obj(d, pn)
        if p is None or p[0].get(b"/Type") != b"/Page":
            return False
        return b"Annual Financial Report" in d
    except Exception:
        return False


def validate_external(path, expected):
    try:
        txt = subprocess.run(["pdftotext", "-f", "1", "-l", "1", str(path), "-"],
                             capture_output=True, text=True, timeout=20)
        info = subprocess.run(["pdfinfo", str(path)], capture_output=True,
                              text=True, timeout=20)
        if txt.returncode == 0 and info.returncode == 0:
            pages = None
            for line in info.stdout.splitlines():
                if line.startswith("Pages:"):
                    pages = int(line.split(":", 1)[1].strip())
            if pages != expected:
                return False, "expected %d pages, got %d" % (expected, pages)
            if TITLE not in txt.stdout:
                return False, "title not found on cover page"
            return True, "page count ok"
    except (FileNotFoundError, subprocess.TimeoutExpired, ValueError):
        pass
    return None


def main():
    if not REPORT.is_file():
        print("error: report.pdf not found", file=sys.stderr)
        return 1
    try:
        original = None
        try:
            info = subprocess.run(["pdfinfo", str(REPORT)], capture_output=True,
                                  text=True, timeout=20)
            for line in info.stdout.splitlines():
                if line.startswith("Pages:"):
                    original = int(line.split(":", 1)[1].strip())
        except (FileNotFoundError, subprocess.TimeoutExpired, ValueError):
            pass
        print("original report.pdf pages: %s" % original)

        build_cover()
        if not (merge_cli() or merge_raw()):
            print("error: no merge path succeeded", file=sys.stderr)
            return 1

        result = None
        if original is not None:
            result = validate_external(MERGED, original + 1)
        if result is None:
            print("warning: no external validator; structural validation only", file=sys.stderr)
            result = (True, "structural validation ok")
        if not result[0]:
            print("error: validation failed: " + result[1], file=sys.stderr)
            return 1
        os.replace(str(MERGED), str(REPORT))
        print("ok: cover page added to report.pdf (title '%s', date '%s'); %s"
              % (TITLE, date_text(), result[1]))
        return 0
    finally:
        for tmp in (COVER, MERGED):
            try:
                tmp.unlink(missing_ok=True)
            except OSError:
                pass


if __name__ == "__main__":
    sys.exit(main())
